<?php
require_once __DIR__.'/v5-common.php';$q=trim((string)($_GET['q']??''));$q=substr($q,0,100);$results=[];$dev=[];$error='';
try{if($q!==''){$db=v5db();$pat='%'.addcslashes($q,'%_').'%';$st=$db->prepare('SELECT id,protocol,title,status,priority FROM sd_tickets WHERE protocol LIKE ? OR title LIKE ? OR device_id LIKE ? ORDER BY created_at DESC LIMIT 30');$st->bind_param('sss',$pat,$pat,$pat);$st->execute();$results=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();require_once __DIR__.'/../php/iot_service.php';if(iotTableExists($db,'iot_devices')){$st=$db->prepare('SELECT device_id,name,status,last_seen FROM iot_devices WHERE device_id LIKE ? OR name LIKE ? LIMIT 30');$st->bind_param('ss',$pat,$pat);$st->execute();$dev=$st->get_result()->fetch_all(MYSQLI_ASSOC);$st->close();}}}catch(Throwable $ex){error_log('[V5 search] '.$ex->getMessage());$error='Não foi possível pesquisar neste momento.';}
v5head('Pesquisa operacional');?><header class="v5-header"><div><div class="v5-kicker">Pesquisa operacional</div><h1>Encontre rapidamente</h1><p>Pesquisa restrita a chamados e dispositivos, acessíveis ao perfil técnico.</p></div><a class="v5-btn" href="central-operacoes.php">Voltar à central</a></header><form method="get" class="v5-panel v5-filters" role="search"><label>Protocolo, assunto ou dispositivo<input type="search" name="q" required maxlength="100" value="<?=v5e($q)?>" placeholder="Ex.: SD-1024"></label><button class="v5-btn v5-primary">Buscar</button></form><?php if($error):?><p class="v5-empty" role="alert"><?=v5e($error)?></p><?php endif;?><?php if($q!==''):?><section class="v5-panel"><h2>Chamados (<?=count($results)?> encontrados, até 30)</h2><?php foreach($results as $r):?><p><a href="service-desk-detalhe.php?id=<?=(int)$r['id']?>"><?=v5e($r['protocol'])?></a> — <?=v5e($r['title'])?> <span class="v5-tag"><?=v5e($r['status'])?></span></p><?php endforeach;?><?php if(!$results):?><p class="v5-empty">Nenhum chamado correspondente.</p><?php endif;?></section><section class="v5-panel"><h2>Dispositivos (<?=count($dev)?> encontrados, até 30)</h2><?php foreach($dev as $d):?><p><a href="iot-dispositivo.php?device=<?=rawurlencode($d['device_id'])?>"><?=v5e($d['device_id'])?></a> — <?=v5e($d['name'])?> · <?=v5e($d['status'])?></p><?php endforeach;?><?php if(!$dev):?><p class="v5-empty">Nenhum dispositivo correspondente.</p><?php endif;?></section><?php endif;?><?php v5foot();?>
